      [T("Руководитель (директор)", "Rahbar (direktor)"), T("да", "ha"), T("да", "ha"), T("Всё: деньги, отчёты, P&L, зарплата, настройки, пользователи, аудит-лог", "Hammasini: pul, hisobotlar, P&L, oylik, sozlamalar, foydalanuvchilar, harakatlar jurnali")],
