      [T("Агент", "Agent"), T("частично", "qisman"), T("да", "ha"), T("Свои магазины, заказы, план, долги, KPI и зарплата", "O'z do'konlari, buyurtmalari, rejasi, qarzlari, KPI si va oyligi")],
